def transitive_closure(adjacency: list[list[int]]) -> list[list[int]]:
    """Warshall's algorithm: entry [i][j] is 1 when j is reachable from i (every node reaches itself)."""
    n: int = len(adjacency)
    reach: list[list[int]] = []
    for i in range(n):
        row: list[int] = []
        for j in range(n):
            if i == j or adjacency[i][j] != 0:
                row.append(1)
            else:
                row.append(0)
        reach.append(row)
    for k in range(n):
        for i in range(n):
            if reach[i][k] == 1:
                for j in range(n):
                    if reach[k][j] == 1:
                        reach[i][j] = 1
    return reach

